"""Ansichts-Einstellungen der Seiten landen in client.json und überleben einen Neustart."""

import json
import urllib.error
import urllib.request

import pytest

import client


def call(port, method="GET", body=None):
    req = urllib.request.Request(f"http://127.0.0.1:{port}/prefs", method=method, data=body,
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=5) as r:
        return json.loads(r.read())


def test_prefs_merge_into_client_json(tmp_path, monkeypatch):
    monkeypatch.setattr(client, "CONFIG", tmp_path / "client.json")
    client.CONFIG.write_text(json.dumps({"server": "1.2.3.4"}), "utf-8")
    port = client.serve_web()
    assert call(port) == {}
    call(port, "POST", b'{"settings": "collapsed"}')
    assert call(port, "POST", b'{"view": "list"}') == {"settings": "collapsed", "view": "list"}
    saved = json.loads(client.CONFIG.read_text("utf-8"))
    assert saved == {"server": "1.2.3.4", "view": {"settings": "collapsed", "view": "list"}}
    with pytest.raises(urllib.error.HTTPError) as err:
        call(port, "POST", b"[1]")
    assert err.value.code == 400
